package tv.vela.launcher;

import android.content.Context;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** One selected clear HLS stream, a bounded private disk ring and a loopback-only player endpoint. */
final class VelaHlsBuffer implements AutoCloseable {
    static final long MAX_BYTES=256L*1024*1024;static final int MAX_SEGMENT=16*1024*1024,MAX_SECONDS=15*60,MAX_SEGMENTS=240;
    static final class Part {final long sequence;final double seconds;final URI url;final boolean discontinuity;Part(long n,double s,URI u,boolean d){sequence=n;seconds=s;url=u;discontinuity=d;}}
    static final class Playlist {long sequence;boolean end;URI variant,init;final List<Part> parts=new ArrayList<>();}
    static Playlist parse(String text,URI base)throws IOException{
        if(text.length()>128*1024||!text.trim().startsWith("#EXTM3U"))throw new IOException("Unsupported HLS");Playlist out=new Playlist();double seconds=0;boolean variant=false,discontinuity=false;long seq=0;
        for(String raw:text.split("\n",4001)){String line=raw.trim();if(line.startsWith("#EXT-X-KEY:")&&!line.contains("METHOD=NONE"))throw new IOException("Protected HLS is played directly");if(line.startsWith("#EXT-X-BYTERANGE"))throw new IOException("Byte-range HLS is played directly");if(line.startsWith("#EXT-X-MEDIA-SEQUENCE:")){try{seq=Long.parseLong(line.substring(22).trim());if(seq<0)throw new NumberFormatException();out.sequence=seq;}catch(NumberFormatException e){throw new IOException("Invalid HLS sequence");}}else if(line.startsWith("#EXT-X-MAP:")){int at=line.indexOf("URI=\"");int end=at<0?-1:line.indexOf('"',at+5);if(at<0||end<0||line.contains("BYTERANGE"))throw new IOException("Unsupported HLS map");out.init=resolve(base,line.substring(at+5,end));}else if(line.startsWith("#EXT-X-STREAM-INF:"))variant=true;else if(line.startsWith("#EXTINF:")){try{seconds=Double.parseDouble(line.substring(8).split(",",2)[0]);if(!Double.isFinite(seconds)||seconds<=0||seconds>120)throw new NumberFormatException();}catch(NumberFormatException e){throw new IOException("Invalid HLS duration");}}else if(line.equals("#EXT-X-DISCONTINUITY"))discontinuity=true;else if(line.equals("#EXT-X-ENDLIST"))out.end=true;else if(!line.isEmpty()&&!line.startsWith("#")){URI u=resolve(base,line);if(variant){if(out.variant==null)out.variant=u;variant=false;}else if(seconds>0){if(out.parts.size()>=1000||seq==Long.MAX_VALUE)throw new IOException("HLS segment limit");out.parts.add(new Part(seq++,seconds,u,discontinuity));seconds=0;discontinuity=false;}}}
        if(out.variant==null&&out.parts.isEmpty())throw new IOException("No HLS segments");return out;
    }
    private static URI resolve(URI base,String value)throws IOException{URI uri;try{if(base.getRawPath()==null||base.getRawPath().isEmpty())base=new URI(base.getScheme(),base.getRawAuthority(),"/",base.getRawQuery(),null);uri=base.resolve(value);}catch(java.net.URISyntaxException bad){throw new IOException("Invalid HLS URL");}catch(RuntimeException bad){throw new IOException("Invalid HLS URL");}if(!LiveTvData.httpUrl(uri.toString()))throw new IOException("Invalid HLS URL");return uri;}
    private static final Set<String> ACTIVE=new HashSet<>();
    private final File directory;private final ServerSocket server;private final String token=VelaConnect.random();private final Thread network,local;private final LinkedHashMap<Long,Part> parts=new LinkedHashMap<>();private volatile boolean closed,failed,end;private volatile HttpURLConnection request;private volatile Socket client;private long bytes;private double duration;private boolean hasInit;private long lastSequence=-1;
    VelaHlsBuffer(Context c,String url)throws IOException{File parent=new File(c.getCacheDir(),"live-buffer");parent.mkdirs();synchronized(ACTIVE){File[] abandoned=parent.listFiles();if(abandoned!=null)for(File dir:abandoned)if(dir.isDirectory()&&!ACTIVE.contains(dir.getName())&&dir.getName().matches("[a-f0-9-]{36}")){File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.isFile())f.delete();dir.delete();}}directory=new File(parent,UUID.randomUUID().toString());if(parent.getUsableSpace()<64L*1024*1024||!directory.mkdir())throw new IOException("Insufficient buffer storage");synchronized(ACTIVE){ACTIVE.add(directory.getName());}server=new ServerSocket();try{server.bind(new InetSocketAddress("127.0.0.1",0));server.setSoTimeout(1000);}catch(IOException failure){try{server.close();}catch(IOException ignored){}directory.delete();synchronized(ACTIVE){ACTIVE.remove(directory.getName());}throw failure;}network=new Thread(()->download(url),"vela-hls-disk-ring");local=new Thread(this::serve,"vela-hls-loopback");network.setPriority(Thread.MIN_PRIORITY);local.setPriority(Thread.MIN_PRIORITY);network.start();local.start();}
    String url(){return "http://127.0.0.1:"+server.getLocalPort()+"/"+token+"/index.m3u8";}
    synchronized double seconds(){return duration;}
    synchronized long bytes(){return bytes;}
    private byte[] fetchText(URI uri)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();fetch(uri,out,128*1024);return out.toByteArray();}
    private void fetch(URI uri,OutputStream out,int limit)throws IOException{HttpURLConnection c=(HttpURLConnection)uri.toURL().openConnection();request=c;c.setConnectTimeout(6000);c.setReadTimeout(6000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Vela");try{if(c.getResponseCode()!=200)throw new IOException("HLS resource unavailable");try(InputStream in=c.getInputStream()){byte[] b=new byte[16*1024];int total=0;for(int n;(n=in.read(b))!=-1;){if(closed||Thread.currentThread().isInterrupted())throw new InterruptedIOException();if((total+=n)>limit)throw new IOException("HLS resource limit");out.write(b,0,n);}}}finally{c.disconnect();request=null;}}
    private void download(String url){try{URI uri=URI.create(url);Playlist list=null;for(int depth=0;depth<3;depth++){list=parse(new String(fetchText(uri),StandardCharsets.UTF_8),uri);if(list.variant==null)break;uri=list.variant;if(depth==2)throw new IOException("Nested HLS limit");}int errors=0;while(!closed){try{if(list.init!=null&&!hasInit){File init=new File(directory,"init.bin");try(OutputStream out=new FileOutputStream(init)){fetch(list.init,out,8*1024*1024);}hasInit=true;}int start=lastSequence<0?Math.max(0,list.parts.size()-3):0;for(int i=start;i<list.parts.size()&&!closed;i++){Part p=list.parts.get(i);if(p.sequence<=lastSequence)continue;File temp=new File(directory,p.sequence+".part"),dest=new File(directory,p.sequence+".seg");try(OutputStream out=new FileOutputStream(temp)){fetch(p.url,out,MAX_SEGMENT);}if(!temp.renameTo(dest))throw new IOException("Buffer write failed");synchronized(this){if(closed){dest.delete();return;}parts.put(p.sequence,p);bytes+=dest.length();duration+=p.seconds;lastSequence=p.sequence;prune();notifyAll();}}end=list.end;if(end)return;errors=0;Thread.sleep(1500);list=parse(new String(fetchText(uri),StandardCharsets.UTF_8),uri);}catch(InterruptedException stop){Thread.currentThread().interrupt();return;}catch(IOException transientError){if(closed)return;if(++errors>3)throw transientError;Thread.sleep(1500);list=parse(new String(fetchText(uri),StandardCharsets.UTF_8),uri);}}}catch(Exception unsupported){failed=true;synchronized(this){notifyAll();}}}
    private void prune(){Iterator<Map.Entry<Long,Part>> it=parts.entrySet().iterator();while(parts.size()>2&&(bytes>MAX_BYTES||directory.getUsableSpace()<32L*1024*1024||duration>MAX_SECONDS||parts.size()>MAX_SEGMENTS)){Map.Entry<Long,Part> old=it.next();File f=new File(directory,old.getKey()+".seg");long n=f.length();if(!f.delete())break;bytes-=n;duration-=old.getValue().seconds;it.remove();}}
    private synchronized byte[] playlist()throws Exception{long until=System.currentTimeMillis()+12000;while(parts.size()<2&&!end&&!failed&&!closed&&System.currentTimeMillis()<until)wait(250);if(parts.isEmpty())throw new IOException("Buffer not ready");double max=1;for(Part p:parts.values())max=Math.max(max,p.seconds);StringBuilder s=new StringBuilder("#EXTM3U\n#EXT-X-VERSION:"+(hasInit?6:3)+"\n#EXT-X-TARGETDURATION:").append((int)Math.ceil(max)).append("\n#EXT-X-MEDIA-SEQUENCE:").append(parts.keySet().iterator().next()).append('\n');if(hasInit)s.append("#EXT-X-MAP:URI=\"init.bin\"\n");for(Part p:parts.values()){if(p.discontinuity)s.append("#EXT-X-DISCONTINUITY\n");s.append("#EXTINF:").append(p.seconds).append(",\n").append(p.sequence).append(".seg\n");}if(end)s.append("#EXT-X-ENDLIST\n");return s.toString().getBytes(StandardCharsets.US_ASCII);}
    private void serve(){while(!closed){try{Socket s=server.accept();client=s;try{s.setSoTimeout(6000);String[] first=VelaConnect.line(s.getInputStream(),1024).split(" ");if(first.length!=3||!first[0].equals("GET"))continue;for(int i=0;i<20;i++)if(VelaConnect.line(s.getInputStream(),2048).isEmpty())break;String prefix="/"+token+"/";if(!first[1].startsWith(prefix))continue;String path=first[1].substring(prefix.length());if(path.equals("index.m3u8")){byte[] body=playlist();header(s,"application/vnd.apple.mpegurl",body.length);s.getOutputStream().write(body);}else if(path.equals("init.bin")||path.matches("[0-9]{1,19}\\.seg")){File file=new File(directory,path);if(!file.isFile())continue;try(InputStream in=new FileInputStream(file)){header(s,"video/mp2t",file.length());byte[] b=new byte[16384];for(int n;(n=in.read(b))!=-1&&!closed;)s.getOutputStream().write(b,0,n);}}}finally{s.close();client=null;}}catch(SocketTimeoutException tick){}catch(Exception invalid){/* No stream URLs or account data are written to logs. */}}}
    private static void header(Socket s,String type,long size)throws IOException{s.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: "+type+"\r\nContent-Length: "+size+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));}
    public synchronized void close(){if(closed)return;closed=true;if(request!=null)request.disconnect();try{server.close();if(client!=null)client.close();}catch(IOException ignored){}network.interrupt();local.interrupt();parts.clear();notifyAll();File[] files=directory.listFiles();if(files!=null)for(File f:files)if(f.isFile())f.delete();directory.delete();synchronized(ACTIVE){ACTIVE.remove(directory.getName());}}
}
